// Frattale animato (fbm 4 ottave, lacunarità 2, gain 0.5).
// NB: NON usiamo NoiseW(). Causa accertata via logcat + test di isolamento sul
// device (Galaxy Tab S9 Ultra, Adreno): NoiseW chiama sys_noise(p * frequency) con
// 'frequency' che cresce a RUNTIME nel suo loop; con argomento runtime l'Adreno fa
// fault GPU (gpuSnapshot -> context lost -> app killed). Con frequenze COSTANTI lo
// stesso noise gira senza problemi. Qui srotoliamo le 4 ottave a mano con fattori
// costanti (2,4,8,16): aspetto identico all'originale, niente fault.
float n1 = sys_noise(pModel * 2.0  + vec3(0.0, t * 0.5, 0.0));
float n2 = sys_noise(pModel * 4.0  + vec3(0.0, t * 0.5, 0.0));
float n3 = sys_noise(pModel * 8.0  + vec3(0.0, t * 0.5, 0.0));
float n4 = sys_noise(pModel * 16.0 + vec3(0.0, t * 0.5, 0.0));
float fractal = (n1 + n2 * 0.5 + n3 * 0.25 + n4 * 0.125) / 1.875;

// fractal in [0,1]. Centriamo tra -0.5 e 0.5 e ne scaliamo la forza.
float bump = (fractal - 0.5) * 0.15;

// Sottraiamo il rilievo dalla superficie
d_surf -= bump;

// TRUCCO DI SICUREZZA PER IL RAY MARCHING:
// Moltiplicando la distanza per 0.5 costringiamo i raggi a rallentare,
// impedendo che trapassino le punte del frattale diventando invisibili!
d_surf *= 0.5;
